**Program.cs** — stdio transport with DI:

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace); // CRITICAL: logs to stderr, not stdout

builder.Services.AddHttpClient();  // registers IHttpClientFactory + HttpClient for DI

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();      // auto-discovers all [McpServerToolType] classes

await builder.Build().RunAsync();
```

**ApiTools.cs** — tool class wrapping a REST API:

```csharp
using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private const string BaseUrl = "https://jsonplaceholder.typicode.com";

    [McpServerTool, Description("Fetch a user by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The user's numeric ID (1-10)")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        return await httpClient.GetStringAsync(
            $"{BaseUrl}/users/{userId}", cancellationToken);
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue
            ? $"{BaseUrl}/posts?userId={userId}"
            : $"{BaseUrl}/posts";

        return await httpClient.GetStringAsync(url, cancellationToken);
    }

    [McpServerTool(ReadOnly = false, Destructive = false),
     Description("Create a new post for a user.")]
    public async Task<string> CreatePost(
        [Description("ID of the user authoring the post")] int userId,
        [Description("Post title")] string title,
        [Description("Post body content")] string body,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { userId, title, body });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync(
            $"{BaseUrl}/posts", content, cancellationToken);
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

---

### How DI Works for MCP Tools

The SDK supports **two injection styles**:

| Style | How it works |
|---|---|
| **Constructor injection** (non-static class, shown above) | Services like `HttpClient`, `ILogger<T>` are injected via primary constructor. The class is resolved from the DI container per-request. |
| **Method parameter injection** (static class) | DI services appear as method parameters alongside tool parameters. The SDK distinguishes them automatically — DI services are **never** exposed in the tool schema. |

**Key rules:**
- `CancellationToken`, `IMcpServer`, `IProgress<T>`, and any DI-registered service are **auto-injected** and hidden from the LLM
- Only parameters with `[Description]` appear in the tool's JSON schema
- `AddHttpClient()` registers both `IHttpClientFactory` and `HttpClient` for injection
- `ILogger<T>` is registered by the host builder by default
- Logging **must** go to stderr (`LogToStandardErrorThreshold`) — stdout is the JSON-RPC transport

To scaffold this project from scratch:
```bash
dotnet new mcpserver -n MyApiServer
# then replace the generated tool class and Program.cs with the code above
```
